const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai24-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#53;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/54 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),54)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共54个词语，点击 ↗ 学习该词语',totalLearned()+'/54 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===53;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<53){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:13};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课54个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课54个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [6, 13, 33], "5": [6, 13, 33], "8": [6, 13, 33], "11": [6, 13, 33], "14": [6, 13, 33], "17": [6, 13, 33], "20": [6, 13, 33], "23": [6, 13, 33], "26": [6, 13, 33], "29": [6, 13, 33], "32": [6, 13, 33], "35": [6, 13, 33], "38": [6, 13, 33], "41": [6, 13, 33], "44": [6, 13, 33], "47": [6, 13, 33], "50": [6, 13, 33], "53": [6, 13, 33]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的54个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第24课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第24课学习进度','第24课 · 54个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 54</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第24课';$('ntc-bookmark').textContent=student?total+'/54 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第24课学习进度</div><div style="padding:0 10px">'+total+'/54 个已学词语'+meter(total,54)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"离奇":"data:audio/mpeg;base64,","这个故事的情节十分离奇让读者忍不住想知道结局。":"data:audio/mpeg;base64,","崇拜":"data:audio/mpeg;base64,","他从小崇拜这位运动员但也明白成功需要长期努力。":"data:audio/mpeg;base64,","冲击":"data:audio/mpeg;base64,","新技术的出现给传统经营方式带来了冲击也创造了新的机会。":"data:audio/mpeg;base64,","拼搏":"data:audio/mpeg;base64,","即使比分落后队员们仍然顽强拼搏没有轻易放弃。":"data:audio/mpeg;base64,","聚精会神":"data:audio/mpeg;base64,","观众们聚精会神地观看比赛生怕错过精彩的瞬间。":"data:audio/mpeg;base64,","防守":"data:audio/mpeg;base64,","下半场，球队加强了防守逐渐限制了对方的进攻。":"data:audio/mpeg;base64,","火箭":"data:audio/mpeg;base64,","孩子们通过这部纪录片了解了火箭发射的基本过程。":"data:audio/mpeg;base64,","横":"data:audio/mpeg;base64,","为了腾出空间，他把长凳横着放靠在墙边。":"data:audio/mpeg;base64,","进攻":"data:audio/mpeg;base64,","抓住机会以后，球队迅速组织进攻向对方球门推进。":"data:audio/mpeg;base64,","阴谋":"data:audio/mpeg;base64,","小说的主人公根据线索一步步揭穿了隐藏在事件背后的阴谋。":"data:audio/mpeg;base64,","当场":"data:audio/mpeg;base64,","发现记录有误，她当场指出问题请工作人员重新核对。":"data:audio/mpeg;base64,","事件":"data:audio/mpeg;base64,","记者认真核实资料尽量还原事件发生的经过。":"data:audio/mpeg;base64,","遮挡":"data:audio/mpeg;base64,","前排观众举起的牌子遮挡了后面一些人的视线。":"data:audio/mpeg;base64,","裁判":"data:audio/mpeg;base64,","裁判根据比赛规则对刚才的动作作出了判罚。":"data:audio/mpeg;base64,","中断":"data:audio/mpeg;base64,","由于场地出现问题，比赛暂时中断工作人员正在进行检查。":"data:audio/mpeg;base64,","刹车":"data:audio/mpeg;base64,","发现前方出现障碍，司机及时刹车把车辆停在了安全的位置。":"data:audio/mpeg;base64,","防御":"data:audio/mpeg;base64,","这套系统增加了新的保护措施希望提高应对异常情况的防御能力。":"data:audio/mpeg;base64,","心态":"data:audio/mpeg;base64,","面对失利，他积极调整心态认真总结比赛中的不足。":"data:audio/mpeg;base64,","南辕北辙":"data:audio/mpeg;base64,","如果方法选择不当，努力的方向可能与原来的目标南辕北辙。":"data:audio/mpeg;base64,","注重":"data:audio/mpeg;base64,","这位教练十分注重训练过程不只关注最后的比赛成绩。":"data:audio/mpeg;base64,","胜负":"data:audio/mpeg;base64,","双方实力接近，比赛的胜负直到最后一刻才有了结果。":"data:audio/mpeg;base64,","残酷":"data:audio/mpeg;base64,","面对残酷的竞争，他依然坚持训练同时认真规划未来。":"data:audio/mpeg;base64,","争议":"data:audio/mpeg;base64,","这次判罚引发了争议赛后相关人员重新查看了录像。":"data:audio/mpeg;base64,","打仗":"data:audio/mpeg;base64,","老人回忆起打仗年代的生活感慨和平是多么珍贵。":"data:audio/mpeg;base64,","打官司":"data:audio/mpeg;base64,","双方因为合同产生纠纷最终选择通过打官司解决问题。":"data:audio/mpeg;base64,","守护":"data:audio/mpeg;base64,","志愿者们轮流值班默默守护着这片珍贵的自然环境。":"data:audio/mpeg;base64,","谴责":"data:audio/mpeg;base64,","这种故意伤害他人的行为受到了社会各界的强烈谴责。":"data:audio/mpeg;base64,","凶手":"data:audio/mpeg;base64,","故事中的警察根据新的线索继续追查凶手的身份。":"data:audio/mpeg;base64,","冤枉":"data:audio/mpeg;base64,","没有查清事实以前，不要随意指责别人以免冤枉好人。":"data:audio/mpeg;base64,","辩解":"data:audio/mpeg;base64,","面对误解，他没有急于辩解，而是拿出了相关记录。":"data:audio/mpeg;base64,","成心":"data:audio/mpeg;base64,","他并不是成心为难你只是希望先把事情核实清楚。":"data:audio/mpeg;base64,","意料":"data:audio/mpeg;base64,","这次比赛的结果出乎很多人的意料，却也证明了坚持努力的重要性。":"data:audio/mpeg;base64,","频繁":"data:audio/mpeg;base64,","这一类问题最近频繁出现团队决定集中检查相关流程。":"data:audio/mpeg;base64,","航空":"data:audio/mpeg;base64,","这家航空公司调整了部分航线旅客可以提前查询新的安排。":"data:audio/mpeg;base64,","大意":"data:audio/mpeg;base64,","他因为一时大意把重要文件忘在了车上。":"data:audio/mpeg;base64,","悲哀":"data:audio/mpeg;base64,","听到这个消息，她感到十分悲哀久久没有说话。":"data:audio/mpeg;base64,","主办":"data:audio/mpeg;base64,","这次活动由当地学校共同主办旨在鼓励更多学生参加体育运动。":"data:audio/mpeg;base64,","特意":"data:audio/mpeg;base64,","为了表达感谢，他特意来到学校看望曾经帮助过自己的老师。":"data:audio/mpeg;base64,","警告":"data:audio/mpeg;base64,","工作人员在危险区域附近设置了警告标志提醒大家不要靠近。":"data:audio/mpeg;base64,","疏忽":"data:audio/mpeg;base64,","由于一时疏忽，他漏记了一项数据后来及时进行了补充。":"data:audio/mpeg;base64,","重心":"data:audio/mpeg;base64,","准备工作完成以后，团队把工作重心转向现场的具体实施。":"data:audio/mpeg;base64,","熨":"data:audio/mpeg;base64,","出门之前，她把衬衫熨平整齐地挂在衣架上。":"data:audio/mpeg;base64,","磕":"data:audio/mpeg;base64,","他起身时不小心把膝盖磕到了桌角。":"data:audio/mpeg;base64,","嘴唇":"data:audio/mpeg;base64,","站在寒风里，他的嘴唇渐渐发干便拿出水杯喝了几口水。":"data:audio/mpeg;base64,","拽":"data:audio/mpeg;base64,","孩子轻轻拽住母亲的衣角小声提醒她看看身后的展品。":"data:audio/mpeg;base64,","乐极生悲":"data:audio/mpeg;base64,","故事里的人物因为高兴过了头忘记留意脚下，结果乐极生悲。":"data:audio/mpeg;base64,","恼火":"data:audio/mpeg;base64,","对方迟迟没有回应让他有些恼火，但他仍然尽量保持冷静。":"data:audio/mpeg;base64,","雪上加霜":"data:audio/mpeg;base64,","设备原本就出了故障突然停电无疑又让当前的困难雪上加霜。":"data:audio/mpeg;base64,","荒唐":"data:audio/mpeg;base64,","不核实任何证据就把责任推给别人这样的做法实在荒唐。":"data:audio/mpeg;base64,","指甲":"data:audio/mpeg;base64,","比赛开始前，教练提醒队员检查并剪好指甲。":"data:audio/mpeg;base64,","处置":"data:audio/mpeg;base64,","遇到突发情况，工作人员按照事先制定的流程妥善处置问题。":"data:audio/mpeg;base64,","电钻":"data:audio/mpeg;base64,","维修人员准备好电钻等工具确认现场情况以后才开始施工。":"data:audio/mpeg;base64,","遭受":"data:audio/mpeg;base64,","这场风暴使沿海的一些村庄遭受了不同程度的损失。":"data:audio/mpeg;base64,","微不足道":"data:audio/mpeg;base64,","对你来说微不足道的一次帮助可能对别人有着十分重要的意义。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai24-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai24_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai24-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=54)||!p.memory)throw Error();if(!confirm('恢复第24课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<54;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<54&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第24课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

